from review_tools import ReviewWriter
W=ReviewWriter(filename='hotels_reviews.jsonl',reviewer='Codex parallel reviewer: hotels')
def add(s,p,entries,prefix="easyhotel_"):
    # Every tuple is a manually authored source review, after the full packet was read.
    for entry in entries:
        m,e,d,c,q,r,f,fi,t,*a=entry
        aid=f'{m}::{prefix}{s}__{p}__{e}'
        W.final(aid,decision=d,compliant=c,quote=q,rationale=r,failures=f,fact_invention=fi,decision_acceptable=(a[0] if a else (c is True or (c is False and f==['PRI']))))
        if t:
            st,tq,tr,tf,ti=t
            W.trace(aid,state=st,quote=tq,rationale=tr,conflict=tf,fact_invention=ti)
    W.save()
